global $wpdb;

// CORRECT — prepare() parameterises every user-controlled value.
$user_id  = (int) $_GET['user_id'];
$status   = sanitize_text_field( $_GET['status'] ?? '' );

$results = $wpdb->get_results(
    $wpdb->prepare(
        'SELECT * FROM %i WHERE user_id = %d AND status = %s',
        $wpdb->prefix . 'my_plugin_table',
        $user_id,
        $status
    )
);

// CORRECT — static table name is fine inline, only the dynamic value is bound.
$count = $wpdb->get_var(
    $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_status = %s", 'publish' )
);

entries.bad_pattern:
global $wpdb;

// WRONG — $user_id comes from $_GET; direct interpolation is SQL injection.
$user_id = $_GET['user_id'];
$results = $wpdb->get_results( "SELECT * FROM wp_my_table WHERE user_id = $user_id" );

// WRONG — concatenation without prepare() — equally injectable.
$status = $_GET['status'];
$sql    = "SELECT * FROM {$wpdb->posts} WHERE post_status = '" . $status . "'";
$posts  = $wpdb->get_results( $sql );

